// Recorremos todos los adjuntos
let newMsgs = [];
for (let i = 0; i < msg.attachments.length; i++) {
    let att = msg.attachments[i];
    // Solo PDFs
    if (att.contentType === "application/pdf" || att.filename.endsWith(".pdf")) {
        newMsgs.push({
            payload: att.content,      // binario
            filename: att.filename, // ruta donde guardarlo
            filepath: env.get('PATH_UNIVERSAL') + att.filename, // ruta donde guardarlo
            log: `File ${att.filename} Procesado.`
        });
    }
}

return [newMsgs];

let pdfFiles = msg.list.filter(f => f.toLowerCase().endsWith(".pdf"));
flow.set("contracts", pdfFiles.length);
return msg;

const contracts = flow.get("contracts") || 0;

let values = "(";

const valoresBase = [0, 0, 0, contracts, 0];  // [validacion, series, activaciones, contratos, devoluciones]

// Añadir valores de datosCompletos según el proceso
msg.payload.forEach(item => {
    switch(item.proceso) {
        case "VALIDADOS":
            valoresBase[0] += item.cantidad;  // ADD a validacion
            break;
        case "SERIES":
            valoresBase[1] += item.cantidad;  // ADD a series
            break;
        case "ACTIVACION":
            valoresBase[2] += item.cantidad;  // ADD a activaciones
            break;        
        case "DEVOLUCION":
            valoresBase[4] += item.cantidad;  // ADD a devoluciones
            break;
    }
});

// JUNTAR todo en el VALUE
values += valoresBase.join(', ') + ")";

const insertQuery = `
INSERT INTO BOT (validacion, series, activaciones, contratos, devoluciones)
VALUES ${values};
`;

msg.log = "Update Table BOT";
msg.topic = insertQuery;
msg.payload = { };
return msg;

