msg.payload = {
        chatId: 5888154022, // Replace with your actual chat ID
        type: "document", // Or "document", "audio", etc.
        content: msg.filepath, // Replace with the actual file path or URL
        caption: msg.filename // Optional
 };
 msg.logs = "Archivos Enviados"
return msg;

// Verificar si payload existe y es un array no vacío
if (msg.payload && Array.isArray(msg.payload) && msg.payload.length > 0) {
    msg.context= "SEND_FILE_ERROR"
    return msg;
} else {
    node.warn("❌ Payload está vacío o no es un array");
    return null; // Detener el flow
}

const AUTHORIZED_ID = 5888154022;
const payload = msg.payload || {};
const chatId = payload.chatId;
const messageType = payload.type || 'message';
const text = String(payload.content || '').trim();
const normalizedText = text.toLowerCase();
const original = msg.originalMessage || {};
const callbackMessage = original.message || {};
const sourceMessageId = payload.messageId || callbackMessage.message_id || null;
const user = original.from || {};
const userId = Number(user.id || 0);
const userName = user.first_name || user.username || 'usuario';
const stateKey = `telegram_state_${chatId}`;
const currentState = flow.get(stateKey) || 'idle';

msg.chatId = chatId;
msg.userId = userId;
msg.userName = userName;
msg.messageType = messageType;
msg.sourceMessageId = sourceMessageId;
msg.stateKey = stateKey;
msg.inputText = text;
msg.normalizedText = normalizedText;
msg.currentState = currentState;

if (!chatId) {
    return null;
}

if (userId !== AUTHORIZED_ID) {
    msg.route = 'unauthorized';
    return msg;
}

if (messageType === 'callback_query') {
    if (text === 'get_op_info') {
        msg.route = 'prompt_op';
        return msg;
    }
    if (text === 'get_error_list') {
        msg.route = 'error_list';
        return msg;
    }
    if (text === 'continue_yes') {
        msg.route = 'prompt_op';
        return msg;
    }
    if (text === 'continue_no') {
        msg.route = 'goodbye';
        return msg;
    }
    msg.route = 'show_menu';
    return msg;
}

if (!text || normalizedText === '/start' || normalizedText === 'start' || normalizedText === 'menu') {
    msg.route = 'show_menu';
    return msg;
}

if (normalizedText === 'get_op_info') {
    msg.route = 'prompt_op';
    return msg;
}

if (normalizedText === 'get_error_list') {
    msg.route = 'error_list';
    return msg;
}

if (currentState === 'awaiting_op') {
    msg.route = 'process_op';
    return msg;
}

msg.route = 'show_menu';
return msg;

if (msg.stateKey) { flow.set(msg.stateKey, 'idle'); }
return [[{
    payload: {
        chatId: msg.chatId,
        type: 'message',
        content: 'Usuario no autorizado.'
    }
}]];

const keyboard = {
    inline_keyboard: [
        [{ text: 'Get_Op_Info', callback_data: 'get_op_info' }],
        [{ text: 'Get_Error_List', callback_data: 'get_error_list' }]
    ]
};
const content = [
    `Hola ${msg.userName}.`,
    'Seleccione un comando:',
    '- Get_Op_Info - Devuelve la informacion de Una Op',
    '- Get_Error_List - Devuelve el Listado de errores'
].join('\n');
if (msg.stateKey) { flow.set(msg.stateKey, 'idle'); }
if (msg.messageType === 'callback_query' && msg.sourceMessageId) {
    return [[{
        payload: {
            chatId: msg.chatId,
            type: 'editMessageText',
            content,
            options: {
                message_id: msg.sourceMessageId,
                reply_markup: keyboard
            }
        }
    }]];
}
return [[{
