// === CONFIG CABECERA PERSONALIZADA (fila 5, columna 2) ===
function writeStyledHeader(sheet, headers, startRow, startCol, bgColor) {
    // Crear la fila de cabecera
    const headerRow = sheet.getRow(startRow);

    headers.forEach((header, index) => {
        const cell = headerRow.getCell(startCol + index);
        cell.value = header;
        cell.font = { name: 'Calibri', bold: true, color: { argb: 'FFFFFFFF' }, size: 11 };
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: bgColor } };
        cell.border = {
            top: { style: 'thin' },
            left: { style: 'thin' },
            bottom: { style: 'thin' },
            right: { style: 'thin' }
        };
    });

    // Importante: confirmar la fila en modo streaming
    headerRow.commit();
}
//////////////////////////////////////////////////////////////////////////////////////////
async function setStyledCell(sheet, cellRef, value, fontSize = 12, bgColor = 'FFFF0000') {
    const cell = sheet.getCell(cellRef);
    cell.value = value;
    cell.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: fontSize };
    cell.alignment = { vertical: 'top', horizontal: 'left' };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: bgColor } };

    // opcional: pequeño delay
    await new Promise(resolve => setTimeout(resolve, 1));
}
///////////////////////////////////////////////////////////////////////////////////////////////////
async function exportLargeExcel(workbook, headers, items, batchSize = 500) {

    let startRow = 6; // datos comienzan debajo de la cabecera
    let startCol = 2;
    const sheet = workbook.addWorksheet('Consulta Stock Series');

    await setStyledCell(sheet, 'B1', 'Plateran', 12);
    await setStyledCell(sheet, 'B3', excell_cell, 12);
    // Ajustar ancho de columna y alto de fila
    sheet.getColumn(1).width = 5; // Columna B
    sheet.getColumn(2).width = 20; // Columna B
    sheet.getColumn(3).width = 60; // Columna B
    sheet.getColumn(4).width = 30; // Columna B
    sheet.getColumn(5).width = 25; // Columna B
    sheet.getColumn(6).width = 20; // Columna B
    sheet.getColumn(7).width = 20; // Columna B

    // === CABECERA ESTILIZADA (fila 5, col 2) ===
    writeStyledHeader(sheet, headers, 5, 2, 'FFFF0000');

    for (let i = 0; i < items.length; i += batchSize) {
        const batch = items.slice(i, i + batchSize);

        batch.forEach((item, batchIndex) => {
            const rowIndex = startRow + i + batchIndex;
            const row = sheet.getRow(rowIndex);
            headers.forEach((header, colIndex) => {
                const cell = row.getCell(startCol + colIndex);
                cell.value = item[header] ?? '';
                cell.font = { name: 'Calibri', size: 11 };
                cell.alignment = { vertical: 'middle', horizontal: 'left' };
                cell.border = {
                    top: { style: 'thin' },
                    left: { style: 'thin' },
                    bottom: { style: 'thin' },
                    right: { style: 'thin' }
                };
            });

            row.commit(); // ✅ escribe la fila en el stream
        });
        await new Promise(r => setTimeout(r, 10));
    }

    await workbook.commit();

}
