function writeStyledHeader(sheet, headers, startRow, startCol, bgColor) {
    // Crear la fila de cabecera
    const headerRow = sheet.getRow(startRow);

    headers.forEach((header, index) => {
        const cell = headerRow.getCell(startCol + index);
        cell.value = header;
        cell.font = { name: 'Calibri', bold: true, color: { argb: 'FFFFFFFF' }, size: 11 };
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: bgColor } };
        cell.border = {
            top: { style: 'thin' },
            left: { style: 'thin' },
            bottom: { style: 'thin' },
            right: { style: 'thin' }
        };
    });

    // Importante: confirmar la fila en modo streaming
    headerRow.commit();
}
//////////////////////////////////////////////////////////////////////////////////////////
async function setStyledCell(sheet, cellRef, value, fontSize = 12, bgColor = 'FFFF0000') {
    const cell = sheet.getCell(cellRef);
    cell.value = value;
    cell.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: fontSize };
    cell.alignment = { vertical: 'top', horizontal: 'left' };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: bgColor } };

    // opcional: pequeño delay
    await new Promise(resolve => setTimeout(resolve, 1));
}
