        const localFilePath = msg.filepath;

        if (!remoteFilePath) throw new Error('Remote path undefined');
        if (!localFilePath) throw new Error('Local path undefined');

        // Conectar al servidor SFTP
        await sftp.connect({
            host: env.get('SFTP_TELEFONICA'),
            port: 22,
            username: env.get('SFTP_USER'),
            password: env.get('SFTP_PASSWORD')
        });

        node.status({ fill: "blue", shape: "dot", text: "Conected ....." });

        let payload;
        node.status({ fill: "green", shape: "dot", text: `Upload File Name ${msg.filename}.` });
        if (Array.isArray(localFilePath)) {
            payload = await Promise.all(localFilePath.map(async (localPath) => {
                localPath = path.normalize(localPath);
                let file = path.basename(localPath);
                await sftp.put(localPath, path.posix.join(remoteFilePath, file));
                return localPath;
            }));
        } else {
            const normalizedPath = path.normalize(localFilePath);
            const file = path.basename(normalizedPath);
            await sftp.put(normalizedPath, path.posix.join(remoteFilePath, file));
            payload = normalizedPath;
        }
        node.status({ fill: "green", shape: "dot", text: "Upload Completed" });
        msg.payload = payload;
        return msg;

    } catch (err) {
        node.error(err.message, msg);
        msg.payload = { error: err.message };
        return msg;
    } finally {
        try { await sftp.end(); } catch (e) { }
        // Estado final
        node.status({ fill: "green", shape: "ring", text: "End Process - " + msg.timestamp.toLocaleTimeString() });

    }
}

