function fmtFecha(v) {
    if (!v) return "";
    let d = v;
    if (!(d instanceof Date)) {
        d = new Date(v);
        if (isNaN(d.getTime())) return String(v);
    }
    const dd = String(d.getDate()).padStart(2, "0");
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const yyyy = d.getFullYear();
    return `${dd}/${mm}/${yyyy}`;
}

