const yTexto = 130;    // debajo del barcode

// Ajuste fino manual si lo ves aún corrido
const ajusteBarcodeX = -8;   // mover barcode izquierda/derecha
const ajusteTextoX = 0;      // mover texto izquierda/derecha

let altoBarcode = 70;

// =========================
// FUNCIONES
// =========================

function estimarAnchoCode128(texto, modulo) {
  return (texto.length * 11 + 35) * modulo;
}

function obtenerModulo(len) {
  if (len <= 6) return 3;
  if (len <= 10) return 2;
  return 1;
}

function obtenerFuente(len) {
  if (len <= 8) return { h: 30, w: 30 };
  if (len <= 14) return { h: 24, w: 24 };
  return { h: 20, w: 20 };
}

function calcularFormato(texto) {
  let len = texto.length;
  let modulo = obtenerModulo(len);
  let ancho = estimarAnchoCode128(texto, modulo);

  while (ancho > anchoEtiqueta && modulo > 1) {
    modulo--;
    ancho = estimarAnchoCode128(texto, modulo);
  }

  let fuente = obtenerFuente(len);
  let altura = altoBarcode;

  if (len > 18) {
    altura = 60;
  }
  if (len > 24) {
    altura = 50;
    fuente = { h: 18, w: 18 };
  }

  return {
    modulo,
    ancho,
    fuente,
    altura
  };
}

function generarBloque(xEtiqueta, texto) {
  const formato = calcularFormato(texto);

  const centroEtiqueta = xEtiqueta + Math.floor(anchoEtiqueta / 2);

  // Centrado del barcode
  let xBarcode = Math.round(centroEtiqueta - (formato.ancho / 2)) + ajusteBarcodeX;

  // Limitar dentro del ancho útil
  const minX = xEtiqueta;
  const maxX = xEtiqueta + anchoEtiqueta;

  if (xBarcode < minX) xBarcode = minX;
  if (xBarcode + formato.ancho > maxX) {
    xBarcode = maxX - formato.ancho;
  }

  // Texto centrado usando bloque
  const xTexto = xEtiqueta + ajusteTextoX;

  return (
    "^BY" + formato.modulo + ",3,80\n" +
    "^FO" + xBarcode + "," + yBarcode + "^BCN," + formato.altura + ",N,N,N\n" +
    "^FD" + texto + "^FS\n" +
    "^FO" + xTexto + "," + yTexto +
    "^A0N," + formato.fuente.h + "," + formato.fuente.w +
    "^FB" + anchoEtiqueta + ",1,0,C\n" +
    "^FD" + texto + "\\&^FS\n"
  );
}

