function cleanLocation(value) {
    return String(value || "")
        .trim()
        .replace(/[\r\n]+/g, " ")
        .replace(/\^|~/g, "")
        .replace(/\\/g, "");
}

function normalizeHeader(value) {
    return String(value || "")
        .trim()
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "");
}

function validateRows(rows) {
    if (!Array.isArray(rows) || rows.length === 0) {
        return { error: "El archivo no contiene ubicaciones para imprimir." };
    }

    const valid = [];
    const errors = [];

    rows.forEach((row, index) => {
        const value = cleanLocation(row.ubiUbicacion || row.UbiUbicacion || row.ubicacion || row);
        const rowNumber = row.index || index + 1;

        if (!value) {
            errors.push(`Fila ${rowNumber}: UbiUbicacion vacío`);
            return;
        }

        if (value.length > 8) {
            errors.push(`Fila ${rowNumber}: ${value} supera 8 caracteres`);
            return;
        }

        valid.push({
            index: valid.length + 1,
            ubiUbicacion: value
        });
    });

    if (errors.length) {
        return { error: errors.slice(0, 5).join(" | ") };
    }

    return { rows: valid };
}

async function parseWorkbook(payload) {
    const rawBase64 = String(payload.base64 || "");
    const base64 = rawBase64.includes(",") ? rawBase64.split(",").pop() : rawBase64;

    if (!base64) {
        return [{ topic: "ubicaciones_label_error", error: "Archivo Excel vacío o inválido." }, null];
    }

    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(Buffer.from(base64, "base64"));

    const worksheet = workbook.worksheets[0];
    if (!worksheet) {
        return [{ topic: "ubicaciones_label_error", error: "El Excel no tiene hojas." }, null];
    }

    const headerRow = worksheet.getRow(1);
    let colIndex = 0;

    headerRow.eachCell((cell, colNumber) => {
        if (normalizeHeader(cell.value) === "ubiubicacion") {
            colIndex = colNumber;
        }
    });

    if (!colIndex) {
        return [{ topic: "ubicaciones_label_error", error: "No se encontró la columna UbiUbicacion." }, null];
    }

    const rows = [];
    worksheet.eachRow((row, rowNumber) => {
        if (rowNumber === 1) return;
        const value = cleanLocation(row.getCell(colIndex).text || row.getCell(colIndex).value);
        if (value) {
            rows.push({
                index: rows.length + 1,
                ubiUbicacion: value
            });
        }
    });

    const validation = validateRows(rows);
    if (validation.error) {
        return [{ topic: "ubicaciones_label_error", error: validation.error }, null];
    }

    flow.set("ubicaciones_rows", validation.rows);

    return [
        {
            topic: "ubicaciones_excel_loaded",
            message: `Archivo cargado: ${validation.rows.length} ubicaciones`,
            payload: {
                rows: validation.rows
            }
        },
        null
    ];
}

