    return [
        {
            topic: "ubicaciones_template",
            payload: {
                fileName: "plantilla_ubicaciones.xlsx",
                mime: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                base64
            }
        },
        null
    ];
}

