}

function getFormat(text) {
    const labelWidth = 799;
    const margin = 48;
    const usableWidth = labelWidth - margin * 2;
    let moduleWidth = 6;
    let width = estimateCode128Width(text, moduleWidth);

    while (width > usableWidth && moduleWidth > 2) {
        moduleWidth--;
        width = estimateCode128Width(text, moduleWidth);
    }

    return {
        moduleWidth,
        width,
        x: Math.max(margin, Math.round((labelWidth - width) / 2)),
        height: 183
    };
}

