function toCellValue(value) {
    if (value === null || value === undefined) return '';
    if (value instanceof Date) return value;
    if (typeof value === 'object') return JSON.stringify(value);
    return value;
}

function toText(value) {
    const normalized = toCellValue(value);
    if (normalized instanceof Date) return normalized.toISOString();
    return String(normalized);
}

function measureWidth(value) {
    return toText(value)
        .split(/\r?\n/)
        .reduce((max, line) => Math.max(max, line.length), 0);
}

function buildColumns(rows, configured) {
    const normalized = [];
    const seen = new Set();

    if (Array.isArray(configured) && configured.length) {
        configured.forEach((col) => {
            let key = '';
            let header = '';

            if (typeof col === 'string') {
                key = col.trim();
                header = key;
            } else if (col && typeof col === 'object') {
                key = String(col.key || col.field || col.name || '').trim();
                header = String(col.header || col.label || col.title || key).trim();
            }

            if (!key || !header || seen.has(key)) {
                return;
            }

            seen.add(key);
            normalized.push({ key, header });
        });

        return normalized;
    }

    rows.forEach((row) => {
        if (!row || typeof row !== 'object' || Array.isArray(row)) return;
        Object.keys(row).forEach((key) => {
            const cleanKey = String(key).trim();
            if (!cleanKey || seen.has(cleanKey)) {
                return;
            }
            seen.add(cleanKey);
            normalized.push({ key: cleanKey, header: cleanKey });
        });
    });

    return normalized;
}

